SELECT n.gender, rt.role, cn.name, COUNT(*)
FROM title as t, movie_companies as mc, company_name as cn, company_type as ct, kind_type as kt, cast_info as ci, name as n, role_type as rt, movie_info as mi1, info_type as it, non_leaf_1484
WHERE (cn.name ILIKE '%im%') AND mc.movie_id = non_leaf_1484.ci_movie_id AND n.id = non_leaf_1484.ci_person_id AND cn.id = mc.company_id AND (mi1.info ILIKE '%sr%') AND (kt.kind ILIKE '%se%') AND (it.id IN ('6')) AND (t.production_year <= 2015) AND kt.id = non_leaf_1484.t_kind_id AND (rt.role IN ('actor','cinematographer','composer','costume designer','director','editor','guest','miscellaneous crew','producer')) AND mc.movie_id = non_leaf_1484.t_id AND ct.id = mc.company_type_id AND (t.production_year >= 1875) AND it.id = non_leaf_1484.mi1_info_type_id;